"use client";

import React from "react";
import { OtpNotificationBanner } from "../common/OtpNotificationBanner";
import { OtpVerificationCardProps } from "./types";
import { useOtpVerification } from "./useOtpVerification";
import { OtpHeader } from "./OtpHeader";
import { OtpAlerts } from "./OtpAlerts";
import { OtpForm } from "./OtpForm";

export type { OtpVerificationCardProps };

export const OtpVerificationCard: React.FC<OtpVerificationCardProps> = ({
  email,
  initialOtp = "",
  onSuccessRedirect = "/login?registered=true",
  isForgotPasswordFlow = false,
  onForgotVerified,
  onBackToLogin,
  title,
  subtitle,
  sourceText,
}) => {
  const {
    otp,
    setOtp,
    activeApiOtp,
    loading,
    resending,
    errorMessage,
    successMessage,
    cooldown,
    handleVerify,
    handleResend,
  } = useOtpVerification({
    email,
    initialOtp,
    onSuccessRedirect,
    isForgotPasswordFlow,
    onForgotVerified,
    onBackToLogin,
  });

  return (
    <div className="w-full">
      {/* Card Header */}
      <OtpHeader email={email} title={title} subtitle={subtitle} />

      {/* OTP Notification Banner (Highlighting OTP from API response) */}
      {activeApiOtp && (
        <div className="mb-5">
          <OtpNotificationBanner
            otp={activeApiOtp}
            email={email}
            sourceText={
              sourceText ||
              (isForgotPasswordFlow ? "Password Reset Code" : "Verification OTP Code")
            }
            onAutoFill={(val) => setOtp(val)}
          />
        </div>
      )}

      {/* Status Messages */}
      <OtpAlerts successMessage={successMessage} errorMessage={errorMessage} />

      {/* Form with Input, Action Button, and Resend Footer */}
      <OtpForm
        email={email}
        otp={otp}
        onOtpChange={(val) => setOtp(val)}
        onSubmit={handleVerify}
        loading={loading}
        resending={resending}
        cooldown={cooldown}
        onResend={handleResend}
        onBackToLogin={onBackToLogin}
      />
    </div>
  );
};
